{
  "service": "gateway",
  "description": "gateway edge proxy",
  "listen": {
    "address": "127.0.0.1",
    "port": 8080
  },
  "tls": {
    "enabled": true,
    "verify_upstream": true,
    "min_version": "1.2"
  },
  "logging": {
    "level": "info",
    "format": "json",
    "sample_rate_pct": 100
  },
  "limits": {
    "max_body_kib": 512,
    "max_connections": 2048,
    "idle_timeout_s": 60
  },
  "features": {
    "compression": true,
    "http2": true,
    "request_ids": true
  },
  "upstreams": [
    {
      "name": "orders",
      "host": "orders.internal",
      "port": 7864,
      "weight": 8,
      "health_check": "/healthz"
    },
    {
      "name": "search",
      "host": "search.internal",
      "port": 9681,
      "weight": 6,
      "health_check": "/healthz"
    },
    {
      "name": "payments",
      "host": "payments.internal",
      "port": 9049,
      "weight": 1,
      "health_check": "/healthz"
    },
    {
      "name": "reviews",
      "host": "reviews.internal",
      "port": 8432,
      "weight": 2,
      "health_check": "/healthz"
    },
    {
      "name": "notifications",
      "host": "notifications.internal",
      "port": 7283,
      "weight": 7,
      "health_check": "/healthz"
    }
  ],
  "routes": [
    {
      "path": "/api/v1/payments/status",
      "upstream": "payments",
      "methods": [
        "GET",
        "POST"
      ],
      "timeout_ms": 5000,
      "retries": 1
    },
    {
      "path": "/api/v1/reviews/refunds",
      "upstream": "reviews",
      "methods": [
        "GET"
      ],
      "timeout_ms": 3000,
      "retries": 0
    },
    {
      "path": "/api/v1/payments/audit",
      "upstream": "payments",
      "methods": [
        "GET",
        "PUT"
      ],
      "timeout_ms": 3000,
      "retries": 0
    },
    {
      "path": "/api/v1/notifications/tokens",
      "upstream": "notifications",
      "methods": [
        "POST"
      ],
      "timeout_ms": 3000,
      "retries": 0
    }
  ]
}

